local UIActionEquipCollectionNode = Class("UIActionEquipCollectionNode")
function UIActionEquipCollectionNode:__init()
    self._data = nil
    self._cb = nil
    self.equipActivityTrans = nil
end

function UIActionEquipCollectionNode:__delete()
    self._data = nil
    self._cb = nil
    self.equipActivityTrans = nil
end

function UIActionEquipCollectionNode:Awake()
    self.equipActivityTrans = self.BtnNode.transform:Find(EquipActivityNodeName)
end

function UIActionEquipCollectionNode:Start()
    SetButtonAction(self.BtnNode, Bind(self, self.OnBtnNode))
end

function UIActionEquipCollectionNode:OnBtnNode()
    if not self._cb then
        return
    end
    self._cb()
end

function UIActionEquipCollectionNode:Refresh(data, ind, cb)
    if not data then
        return
    end

    self._cb = cb
    self._data = data
    self._ind = checkNumber(ind)

    self:FillSelf()
end

function UIActionEquipCollectionNode:FillSelf()
    local isUnlock = GameUtils.IsUnlocked(self._data.unlockType, self._data.unlockNum, self._data.unlockId)   
    self:FillSelect(false)
    if isUnlock then
        local t = CfUtils.Split(self._data.sheetId)
        if #t == 1 then
            ---常规装备类型
            --@type PlayerComponent
            local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            local status = checkNumber(playerComponent.playerDojo.consumeCopyActivity.status)
            local times = checkNumber(playerComponent.playerDojo.consumeCopyActivity.residueNum)
            CfUtils.SetActive(self.equipActivityTrans, status == 1)
            if status == 1  then
                CfUtils.FillText(self.equipActivityTrans:Find("RemainTimes/TextDesc"),  localize('活动进行中'))
            end
        end
    end
    CfUtils.FillImage(self.ImgMapRegion, self._data.Image)
    CfUtils.FillText(self.TextName, self._data.lable)
    self.ImgMapRegion.transform:GetComponent(typeof(UIGrayGraphics)):MarkGray(not isUnlock)

    self._co = CfUtils.PlayDelayShowAnimate(self.Cell_Root, self._ind, 0.05, 0, "ActionEquipCollectionDialog_LeftCell_DropDown")
end

function UIActionEquipCollectionNode:FillSelect(isSelect)
    local isUnlock = GameUtils.IsUnlocked(self._data.unlockType, self._data.unlockNum, self._data.unlockId)   
    if not isSelect then
        if isUnlock then
            CfUtils.PlayAnimation(self.controller.gameObject, "ActionEquipCollectionDialog_LeftCell_Normal")
        else
            CfUtils.PlayAnimation(self.controller.gameObject, "ActionEquipCollectionDialog_LeftCell_Lock")
        end
    else
        if isUnlock then
            CfUtils.PlayAnimation(self.controller.gameObject, "ActionEquipCollectionDialog_LeftCell_Normal_Select")
        else
            CfUtils.PlayAnimation(self.controller.gameObject, "ActionEquipCollectionDialog_LeftCell_Lock_Select")
        end
    end
end


function UIActionEquipCollectionNode:OnDestroy()
    if self._co then 
        cs_coroutine.stop(self._co)
        self._co = nil
    end

    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActionEquipCollectionNode